cbc-mac.pseudocode:
def xor(a, b):
    return bytes(x ^ y for x, y in zip(a, b))

def cbc_mac(E, key, blocks, block_size=16):
    # 고정 길이 메시지 전제, IV는 0 고정
    state = bytes(block_size)
    for m in blocks:
        state = E(key, xor(state, m))  # 중간값은 출력 안 함
    return state  # 마지막 블록이 태그

def verify(E, key, blocks, tag):
    return constant_time_eq(cbc_mac(E, key, blocks), tag)
